import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { objectsEqual } from 'lib/utils/objects'
import { teamLogic } from 'scenes/teamLogic'

import type { TeamPublicType, TeamType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestBlocklistLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    currentTeamLoading: boolean // teamLogic
    blockedHosts: string[]
    blockedIps: string[]
    draftBlockedHosts: string[] | null
    draftBlockedIps: string[] | null
    hasUnsavedChanges: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestBlocklistLogicActions {
    updateCurrentTeam: (payload: Partial<TeamType>) => Partial<TeamType> // teamLogic
    updateCurrentTeamSuccess: (
        currentTeam: TeamPublicType | TeamType,
        payload?: Partial<TeamType> | undefined
    ) => {
        currentTeam: TeamPublicType | TeamType
        payload?: Partial<TeamType>
    } // teamLogic
    clearDrafts: () => {
        value: true
    }
    saveBlocklist: () => {
        value: true
    }
    setBlockedHosts: (blockedHosts: string[]) => {
        blockedHosts: string[]
    }
    setBlockedIps: (blockedIps: string[]) => {
        blockedIps: string[]
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestBlocklistLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        blockedHosts: (draftBlockedHosts: string[] | null, currentTeam: TeamPublicType | TeamType | null) => string[]
        blockedIps: (draftBlockedIps: string[] | null, currentTeam: TeamPublicType | TeamType | null) => string[]
        hasUnsavedChanges: (
            draftBlockedHosts: string[] | null,
            draftBlockedIps: string[] | null,
            currentTeam: TeamPublicType | TeamType | null
        ) => boolean
    }
}

export type featureFlagRequestBlocklistLogicType = MakeLogicType<
    featureFlagRequestBlocklistLogicValues,
    featureFlagRequestBlocklistLogicActions,
    Record<string, any>,
    featureFlagRequestBlocklistLogicMeta
>

export const featureFlagRequestBlocklistLogic = kea<featureFlagRequestBlocklistLogicType>([
    path(['products', 'feature_flags', 'frontend', 'featureFlagRequestBlocklistLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentTeamLoading']],
        actions: [teamLogic, ['updateCurrentTeam', 'updateCurrentTeamSuccess']],
    })),
    actions({
        setBlockedHosts: (blockedHosts: string[]) => ({ blockedHosts }),
        setBlockedIps: (blockedIps: string[]) => ({ blockedIps }),
        saveBlocklist: true,
        clearDrafts: true,
    }),
    reducers({
        // null until the admin edits the list. Other settings on the page update the team too,
        // and a draft that follows every team update would lose unsaved edits.
        draftBlockedHosts: [
            null as string[] | null,
            {
                setBlockedHosts: (_, { blockedHosts }) => blockedHosts,
                clearDrafts: () => null,
            },
        ],
        draftBlockedIps: [
            null as string[] | null,
            {
                setBlockedIps: (_, { blockedIps }) => blockedIps,
                clearDrafts: () => null,
            },
        ],
    }),
    selectors({
        blockedHosts: [
            (s) => [s.draftBlockedHosts, s.currentTeam],
            (draftBlockedHosts: string[] | null, currentTeam: TeamPublicType | TeamType | null): string[] =>
                draftBlockedHosts ?? currentTeam?.feature_flag_policy_config?.blocked_hosts ?? [],
        ],
        blockedIps: [
            (s) => [s.draftBlockedIps, s.currentTeam],
            (draftBlockedIps: string[] | null, currentTeam: TeamPublicType | TeamType | null): string[] =>
                draftBlockedIps ?? currentTeam?.feature_flag_policy_config?.blocked_ips ?? [],
        ],
        hasUnsavedChanges: [
            (s) => [s.draftBlockedHosts, s.draftBlockedIps, s.currentTeam],
            (
                draftBlockedHosts: string[] | null,
                draftBlockedIps: string[] | null,
                currentTeam: TeamPublicType | TeamType | null
            ): boolean => {
                const config = currentTeam?.feature_flag_policy_config
                return (
                    (draftBlockedHosts !== null && !objectsEqual(draftBlockedHosts, config?.blocked_hosts ?? [])) ||
                    (draftBlockedIps !== null && !objectsEqual(draftBlockedIps, config?.blocked_ips ?? []))
                )
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        saveBlocklist: () => {
            actions.updateCurrentTeam({
                feature_flag_policy_config: { blocked_hosts: values.blockedHosts, blocked_ips: values.blockedIps },
            })
        },
        updateCurrentTeamSuccess: ({ payload }) => {
            // Only a successful blocklist save clears the drafts. A save of another team setting keeps
            // them, and a failed save keeps them too, so the admin can fix the entry the API rejected.
            const config = payload?.feature_flag_policy_config
            if (config?.blocked_hosts !== undefined || config?.blocked_ips !== undefined) {
                actions.clearDrafts()
            }
        },
    })),
])
